sys_script_include.script:
var AdmissionMeritEngine = Class.create();
AdmissionMeritEngine.prototype = {
    initialize: function() {},

    /**
     * Calculates composite merit score: (10th% + 12th% + JEE) / 3
     */
    calculateMeritScore: function(appGR) {
        if (!appGR || !appGR.isValidRecord()) return 0;
        var m10 = parseFloat(appGR.getValue('class_10_percentage')) || 0;
        var m12 = parseFloat(appGR.getValue('class_12_percentage')) || 0;
        var jee = parseFloat(appGR.getValue('jee_score')) || 0;
        var composite = (m10 + m12 + jee) / 3;
        return parseFloat(composite.toFixed(2));
    },

    /**
     * 4-Tier Tie-Breaker Comparison:
     * 1. Overall composite merit
     * 2. JEE Score
     * 3. Secondary Average (10th + 12th) / 2
     * 4. Max individual (10th or 12th)
     * 5. Seniority by DOB
     */
    compareApplicants: function(a, b) {
        // Tier 0: Composite Merit
        if (b.merit !== a.merit) return b.merit - a.merit;

        // Tier 1: JEE Score
        if (b.jee !== a.jee) return b.jee - a.jee;

        // Tier 2: Average of 10th and 12th
        var avgA = (a.m10 + a.m12) / 2;
        var avgB = (b.m10 + b.m12) / 2;
        if (avgB !== avgA) return avgB - avgA;

        // Tier 3: Highest individual score
        var maxA = Math.max(a.m10, a.m12);
        var maxB = Math.max(b.m10, b.m12);
        if (maxB !== maxA) return maxB - maxA;

        // Tier 4: Seniority by DOB (older first)
        if (a.dob && b.dob) {
            return a.dob < b.dob ? -1 : 1;
        }

        return 0;
    },

    /**
     * Ranks all verified applications for a college program
     */
    rankApplicants: function(collegeId, programId) {
        var gr = new GlideRecord('x_1790229_edusph_0_admission_application');
        gr.addQuery('college', collegeId);
        gr.addQuery('program', programId);
        gr.addQuery('status', 'CONTAINS', 'verified').addOrCondition('status', 'in merit');
        gr.query();

        var list = [];
        while (gr.next()) {
            var merit = this.calculateMeritScore(gr);
            list.push({
                sys_id: gr.getUniqueValue(),
                app_no: gr.getValue('app_no'),
                category: gr.getValue('category'),
                merit: merit,
                jee: parseFloat(gr.getValue('jee_score')) || 0,
                m10: parseFloat(gr.getValue('class_10_percentage')) || 0,
                m12: parseFloat(gr.getValue('class_12_percentage')) || 0,
                dob: gr.getValue('date_of_birth') || ''
            });
        }

        var self = this;
        list.sort(function(a, b) { return self.compareApplicants(a, b); });

        // Update merit scores and set status to 'in merit'
        for (var i = 0; i < list.length; i++) {
            var upd = new GlideRecord('x_1790229_edusph_0_admission_application');
            if (upd.get(list[i].sys_id)) {
                upd.setValue('merit_score', list[i].merit);
                upd.setValue('status', 'in merit');
                upd.update();
            }
        }

        return list;
    },

    type: 'AdmissionMeritEngine'
};
